import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa v1.28 released — Realtime 深化 II (WebRTC + WebTransport + HTTP/3 + QUIC multiplexing + 3 dogfood app + real driver env-gate)","description":"","frontmatter":{"title":"kiwa v1.28 released — Realtime 深化 II (WebRTC + WebTransport + HTTP/3 + QUIC multiplexing + 3 dogfood app + real driver env-gate)","emoji":"📡","type":"tech","topics":["oss","typescript","webrtc","webtransport","kiwa"],"published":true},"headers":[],"relativePath":"announcements/v1.28/zenn-article.md","filePath":"announcements/v1.28/zenn-article.md"}'),o={name:"announcements/v1.28/zenn-article.md"};function s(n,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="kiwa-v1-28-released" tabindex="-1">kiwa v1.28 released <a class="header-anchor" href="#kiwa-v1-28-released" aria-label="Permalink to &quot;kiwa v1.28 released&quot;">​</a></h1><p>v1.28 は kiwa の 18 milestone 目です。 v1.13 (時間軸、 <code>@kiwa-lab/realtime</code> v0.1 で 4 provider Supabase / Ably / Pusher / Socket.io × 5 base semantics 統一 mock を land) を基盤に、 v1.28 は同 provider mock の上に <strong>advanced realtime production semantics 8 axis (WebRTC + WebTransport + HTTP/3 + QUIC multiplexing) + 3 dogfood app + real driver env-gate + protocol-neutral state machine + strict transition guard</strong> を land。 v0.1 4 provider mock + 5 base semantics API (<code>presence</code> / <code>broadcast</code> / <code>postgres_changes</code> / <code>room</code> / <code>reconnect</code>) は first-line contract のまま維持 (v0.1 signature 完全維持)、 8 新 axis (<code>webrtc-signaling</code> / <code>webrtc-data-channel</code> / <code>webrtc-media-track</code> / <code>webrtc-ice-stun-turn</code> / <code>webtransport-unidirectional</code> / <code>webtransport-bidirectional</code> / <code>http3-push</code> / <code>quic-multiplexing</code>) は second-line envelope として並走。 <code>@kiwa-lab/realtime</code> v0.1.1 → v0.2.0 minor bump は 8 axis advanced-transport semantics + 24-row 3×8 fidelity grid + real driver env-gate を反映。 v1.11 以降の連続完遂 17 milestone (release gate → 非決定性 → 時間軸 → 横軸拡張 → AI-LLM 深化 → component 縦軸 → Observability v2 → Blockchain 深化 → Framework 深化 → Streaming 深化 → Auth 深化 → Auth 深化 II → Payment 深化 → Edge / Serverless 深化 → Perf-harness sweep → Database 深化 → Mutation testing sweep) を受けて、 v1.28 は Realtime 深化 II milestone、 kiwa runtime fixture 34 packages はそのまま維持 (realtime 既存 package の minor 拡張)。</p><h2 id="主な追加" tabindex="-1">主な追加 <a class="header-anchor" href="#主な追加" aria-label="Permalink to &quot;主な追加&quot;">​</a></h2><h3 id="kiwa-lab-realtime-v0-2-0-advanced-realtime-semantics-8-axis-24-row-3×8-grid-real-driver-env-gate" tabindex="-1"><code>@kiwa-lab/realtime</code> v0.2.0 (advanced realtime semantics 8 axis + 24-row 3×8 grid + real driver env-gate) <a class="header-anchor" href="#kiwa-lab-realtime-v0-2-0-advanced-realtime-semantics-8-axis-24-row-3×8-grid-real-driver-env-gate" aria-label="Permalink to &quot;`@kiwa-lab/realtime` v0.2.0 (advanced realtime semantics 8 axis + 24-row 3×8 grid + real driver env-gate)&quot;">​</a></h3><p>v1.13 で land した 4 provider mock (<code>createSupabaseRealtimeMock</code> / <code>createAblyMock</code> / <code>createPusherMock</code> / <code>createSocketIoMock</code>) + 5 base semantics (<code>presence</code> / <code>broadcast</code> / <code>postgres_changes</code> / <code>room</code> / <code>reconnect</code>) の signature を完全維持したまま、 v1.28 は <code>packages/realtime/src/semantics/*</code> に 8 axis の pure state-machine helper を追加。 全 helper は pure function (no adapter / no browser / no signaling server) で決定論的、 test / fixture / release gate で reproducible。</p><ul><li><code>webrtc-signaling.ts</code> — offer / answer + SDP + ICE candidate + renegotiation (4 step SDP negotiation state machine + ICE trickle interleave)</li><li><code>webrtc-data-channel.ts</code> — ordered / unordered + reliable + maxRetransmits + binaryType (<code>arraybuffer</code> / <code>blob</code>)</li><li><code>webrtc-media-track.ts</code> — getUserMedia mock + MediaStream + simulcast + track add / remove (video / audio track lifecycle)</li><li><code>webrtc-ice-stun-turn.ts</code> — candidate gathering + connectivity check + TURN relay + trickle ICE (STUN binding + TURN allocate)</li><li><code>webtransport-unidirectional.ts</code> — uni stream + Datagram + reset (HTTP/3 CONNECT + unidirectional flag)</li><li><code>webtransport-bidirectional.ts</code> — bi stream + flow control + backpressure (bidirectional stream + credit-based flow)</li><li><code>http3-push.ts</code> — server push + prioritization + <code>PUSH_PROMISE</code> + cancellation (<code>SETTINGS_ENABLE_PUSH</code> gate)</li><li><code>quic-multiplexing.ts</code> — stream multiplex + stream priority + HPACK dynamic table + 0-RTT resumption</li></ul><h3 id="_4-rule-ssot" tabindex="-1">4 rule SSOT <a class="header-anchor" href="#_4-rule-ssot" aria-label="Permalink to &quot;4 rule SSOT&quot;">​</a></h3><p><code>docs/concepts/webrtc-webtransport-testing.md</code> は kiwa realtime 全 protocol の 4 rule を単一 SSOT 化。</p><ol><li><strong>8 axis SSOT</strong> — WebRTC / WebTransport / HTTP/3 を単一「realtime」抽象で wrap しない。 各 protocol の shape を axis 名で名指しし、 fidelity regression は 24 row grid 上の単一 cell 変化として surface する。 <code>webrtc-data-channel</code> reliable mode の regression は「<code>webrtc-data-channel</code> × <code>Ably</code> cell が FAIL」 として visible、 24 のいずれかで shift しうる percentage ではない。</li><li><strong>3 protocol neutral state machine</strong> — WebRTC / WebTransport / HTTP/3 の 3 protocol は共通の event 名 routing table (<code>emit</code> / <code>on</code> / <code>close</code> / <code>error</code>) に neutralize、 provider-specific transition table は各 axis file 内 pure function に閉じ込め。 protocol 越しの assertion は同 event 名で書ける、 protocol 越しの regression は同 assertion で catch できる。</li><li><strong>24-row fidelity grid</strong> — 8 axis × 3 protocol = 24 row grid、 各 cell は「axis × protocol」 pair の fidelity を single boolean で expose。 <code>collectFidelityCoverage()</code> は 24 row grid を JSON で return、 release-gate は grid の PASS 率を fidelity axis に統合。 「realtime coverage 87 %」 のような percentage は使わない (24 のいずれかで shift しうるため)。</li><li><strong>real driver env-gate</strong> — v1.13 4 provider mock は default で pure mock、 <code>KIWA_MODE=real</code> env-gate で real driver (coturn / aioquic / nginx-quic testcontainers) に opt-in。 real driver path は同じ axis 名 + fidelity grid + strict transition guard を使うので、 mock → real の切替は env 1 個 (<code>KIWA_MODE=real</code>) で完結、 assertion は 1 行も変えない。</li></ol><h3 id="v1-28-1-realtime-v0-2-advanced-semantics-issue-977" tabindex="-1">v1.28-1 realtime v0.2 advanced semantics (Issue #977) <a class="header-anchor" href="#v1-28-1-realtime-v0-2-advanced-semantics-issue-977" aria-label="Permalink to &quot;v1.28-1 realtime v0.2 advanced semantics (Issue #977)&quot;">​</a></h3><p><code>@kiwa-lab/realtime</code> v0.2 で 8 axis × 3 protocol = 24 row fidelity grid + real-vs-mock fidelity harness + 60 semantics behavior test + v1.13 4 provider (Supabase / Ably / Pusher / Socket.io) に real driver env-gate 追加。 各 axis file は pure state-machine helper で strict transition guard、 決定論的・ adapter-free・ network-free。 <code>packages/realtime/src/semantics/*</code> 8 file + 60 vitest all-PASS。</p><h3 id="v1-28-2-dogfood-nextjs-webrtc-video-app-issue-978" tabindex="-1">v1.28-2 dogfood-nextjs-webrtc-video-app (Issue #978) <a class="header-anchor" href="#v1-28-2-dogfood-nextjs-webrtc-video-app-issue-978" aria-label="Permalink to &quot;v1.28-2 dogfood-nextjs-webrtc-video-app (Issue #978)&quot;">​</a></h3><p>Next.js 15 App Router + mediasoup SFU + coturn TURN server (testcontainers) + WebRTC video/audio + P2P + simulcast + ICE restart。 realtime video call room + track add/remove + network flap 経由の reconnect + 36 vitest all-PASS with <code>KIWA_MODE=real</code> env-gate で coturn opt-in。</p><h3 id="v1-28-3-dogfood-nuxt-webtransport-stream-app-issue-979" tabindex="-1">v1.28-3 dogfood-nuxt-webtransport-stream-app (Issue #979) <a class="header-anchor" href="#v1-28-3-dogfood-nuxt-webtransport-stream-app-issue-979" aria-label="Permalink to &quot;v1.28-3 dogfood-nuxt-webtransport-stream-app (Issue #979)&quot;">​</a></h3><p>Nuxt 3 + WebTransport unidirectional + bidirectional stream + HTTP/3 + Datagram + connection migration + 0-RTT resumption。 edge streaming with backpressure + network change 越しの connection migration + aioquic testcontainers fidelity harness + 30 vitest all-PASS。</p><h3 id="v1-28-4-dogfood-sveltekit-http3-multiplex-app-issue-980-982-follow-up" tabindex="-1">v1.28-4 dogfood-sveltekit-http3-multiplex-app (Issue #980, #982 follow-up) <a class="header-anchor" href="#v1-28-4-dogfood-sveltekit-http3-multiplex-app-issue-980-982-follow-up" aria-label="Permalink to &quot;v1.28-4 dogfood-sveltekit-http3-multiplex-app (Issue #980, #982 follow-up)&quot;">​</a></h3><p>SvelteKit + nginx-quic HTTP/3 + QUIC multiplex + stream priority + HPACK dynamic table + 0-RTT resumption。 multi-stream + priority scheduling + HPACK observation + 32 vitest + adversarial-review 4 finding (closeStream FIN emission + HPACK metrics teardown + 0-RTT origin isolation + priority range validation) を follow-up PR #982 で吸収。</p><h3 id="v1-28-5-docs-補強-issue-983" tabindex="-1">v1.28-5 docs 補強 (Issue #983) <a class="header-anchor" href="#v1-28-5-docs-補強-issue-983" aria-label="Permalink to &quot;v1.28-5 docs 補強 (Issue #983)&quot;">​</a></h3><p><code>docs/tutorials/52-webrtc-video-signaling.md</code> (WebRTC video signaling + SFU vs P2P 選択規範) + <code>docs/tutorials/53-webtransport-stream.md</code> (WebTransport stream + HTTP/3 Datagram) + <code>docs/tutorials/54-http3-multiplex.md</code> (HTTP/3 multiplex + HPACK dynamic table + 0-RTT resumption) + <code>docs/concepts/webrtc-webtransport-testing.md</code> (8 axis SSOT + P2P vs SFU 選択規範 + 3 protocol fidelity table) + <code>docs/migrations/v1.27-to-v1.28.md</code> (additive-only migration guide) を新規追加、 v0.2 API と直接照合可能な 30 snippet-validation test を <code>packages/realtime/tests/docs-tutorial-v1.28.test.ts</code> に land、 tutorial の code snippet drift を構造的に遮断 (v1.22-1.27 pattern の 7 度目の適用、 7 milestone 連続 snippet test 化 pattern)。</p><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#977 / #978 / #979 / #980 / #983 / #976)</li><li><strong>6 PRs merged</strong> (v1.28-1 through v1.28-6 + follow-up #982 adversarial-review)</li><li><strong>1 npm minor bump</strong> (<code>@kiwa-lab/realtime</code> v0.1.1 → v0.2.0) — kiwa runtime fixture count stays 34</li><li><strong>8 axes</strong> on advanced realtime semantics (WebRTC 4 + WebTransport 2 + HTTP/3 1 + QUIC 1)</li><li><strong>3 protocol × 8 axis = 24 row fidelity grid</strong></li><li><strong>3 dogfood apps</strong> (Next.js + mediasoup SFU + coturn / Nuxt + WebTransport + aioquic / SvelteKit + nginx-quic HTTP/3) — 36 + 30 + 32 = <strong>98 dogfood vitest</strong> total</li><li><strong>30 snippet-validation tests</strong> in <code>packages/realtime/tests/docs-tutorial-v1.28.test.ts</code></li></ul><h2 id="_17-milestone-streak" tabindex="-1">17-milestone streak <a class="header-anchor" href="#_17-milestone-streak" aria-label="Permalink to &quot;17-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (非決定性) → v1.13 (時間軸) → v1.14 (横軸拡張) → v1.15 (AI-LLM 深化) → v1.16 (component 縦軸) → v1.17 (Observability v2) → v1.18 (Blockchain 深化) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → v1.23 (Payment 深化) → v1.24 (Edge / Serverless 深化) → v1.25 (Perf-harness sweep) → v1.26 (Database 深化) → v1.27 (Mutation testing sweep) → <strong>v1.28 (Realtime 深化 II)</strong>。 v1.11 以降全 milestone で 6 sub-Issue 完遂維持。</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100 % milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth II (SurrealDB / EdgeDB / Turso / CockroachDB / TimescaleDB / QuestDB)</li><li>Perf-harness sweep II — real-machine baseline (macOS ARM64 + Linux x86_64 + Windows x86_64 3 hardware matrix + CI reproducibility harness)</li><li>Mutation sweep II — property-based mutation (Stryker + fast-check integration + shrink parser)</li><li>Realtime depth III — WebCodecs / WebGPU compute + AV1/VP9 hardware encoding + WHIP/WHEP ingest fidelity</li></ul><p>feedback welcome。</p><h2 id="参照" tabindex="-1">参照 <a class="header-anchor" href="#参照" aria-label="Permalink to &quot;参照&quot;">​</a></h2><ul><li>Repo ... <a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></li><li>Docs ... <a href="https://cardene777.github.io/kiwa/" target="_blank" rel="noreferrer">https://cardene777.github.io/kiwa/</a></li><li>Roadmap ... <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a></li><li>v1.28 parent Issue ... <a href="https://github.com/cardene777/kiwa/issues/970" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/issues/970</a></li><li>WebRTC / WebTransport testing SSOT ... <a href="https://cardene777.github.io/kiwa/concepts/webrtc-webtransport-testing" target="_blank" rel="noreferrer">https://cardene777.github.io/kiwa/concepts/webrtc-webtransport-testing</a></li></ul>',28)])])}const v=t(o,[["render",s]]);export{m as __pageData,v as default};
